from typing import List

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n, m = len(nums), len(queries)

        def can(k: int) -> bool:
            for i, target in enumerate(nums):
                if target == 0:
                    continue
                bits = 1  # bit s means sum s is achievable
                mask = (1 << (target + 1)) - 1
                found = False
                for l, r, val in queries[:k]:
                    if l <= i <= r:
                        bits |= bits << val
                        bits &= mask
                        if (bits >> target) & 1:
                            found = True
                            break
                if not found:
                    return False
            return True

        if can(0):
            return 0
        if not can(m):
            return -1

        left, right = 1, m
        while left < right:
            mid = (left + right) // 2
            if can(mid):
                right = mid
            else:
                left = mid + 1

        return left
